"""The expected results are generated by TypeScript, never by the implementation under test."""
import json
import math
from pathlib import Path
import pytest
from valuation.comps import DEFAULTS, LEGACY, DECLARED, comparables, resolve, from_resolved, weighted_quantile, weigh

FIXTURE = Path(__file__).resolve().parents[2] / 'app/src/engines/valuation/fixtures/comps-parity.json'


def test_fixture_exists():
    assert FIXTURE.exists(), 'TypeScript parity fixture is missing'


def assert_same(actual, expected, path='result'):
    if isinstance(expected, dict):
        assert actual.keys() == expected.keys(), path
        for k in expected:
            assert_same(actual[k], expected[k], path + '.' + k)
    elif isinstance(expected, list):
        assert len(actual) == len(expected), path
        for i, (a, b) in enumerate(zip(actual, expected)):
            assert_same(a, b, f'{path}[{i}]')
    elif isinstance(expected, float):
        assert math.isclose(actual, expected, abs_tol=1e-10, rel_tol=1e-12), path
    else:
        assert actual == expected, path


def test_typescript_parity():
    data = json.loads(FIXTURE.read_text())
    assert_same(DECLARED, data['declared'])
    for case in data['cases']:
        params = {**(LEGACY if case.get('legacy') else DEFAULTS), **case.get('params', {})}
        assert_same(comparables(case['target'], case['rows'], case['as_of'], params), case['expected'], case['name'])


def test_registry_reads_and_missing_resolved_names():
    r = resolve(lambda name, scope: {'value': next(e['prior'] for e in DECLARED if e['name'] == name), 'version': 7}, {'kind': 'shoes'})
    assert set(r['versions'].values()) == {7}
    del r['values']['valuation_anchor_k']
    with pytest.raises(ValueError, match='valuation_anchor_k'):
        from_resolved(r)


@pytest.mark.parametrize('bad', [-1, 1.5, math.nan, math.inf, 2**53])
def test_invalid_money(bad):
    with pytest.raises(ValueError, match='cents'):
        weighted_quantile([bad], [1], .5)


@pytest.mark.parametrize('bad', [-1, 1.5, math.nan, math.inf, 2**53])
@pytest.mark.parametrize('sold_at', ['2019-01-01', '2021-01-01'])
def test_invalid_money_is_refused_before_discarding_duplicate_or_future_row(bad, sold_at):
    valid = {'comp_id': 'same', 'site': 'ebay', 'sold_at': '2019-12-01', 'price_cents': 10000,
             'kind': 'sold', 'level': 'variant', 'condition': 'good', 'w_match': 1, 'w_extract': 1}
    with pytest.raises(ValueError, match='price_cents'):
        weigh([valid, {**valid, 'sold_at': sold_at, 'price_cents': bad}], '2020-01-01')


def test_history_same_time_sales_share_the_prior_window_and_include_its_boundary():
    from valuation.comps import fit_history
    def sale(id, at, price):
        return {'comp_id': id, 'product_id': 'p', 'family_id': 'f', 'site': 'ebay',
                'sold_at': at, 'price_cents': price, 'kind': 'sold', 'may_model': True}
    rows = [sale('old', '2019-12-31', 1000), sale('a', '2020-01-01', 10000),
            sale('b', '2020-01-01', 20000), sale('c', '2020-03-31', 15000),
            sale('d', '2020-03-31', 30000)]
    fitted = fit_history(rows, '2020-04-01')
    before = (math.log(10) + math.log(20)) / 2
    assert fitted['index']('f', '2020-03-31') == before
    # March 31 is exactly 90 days after January 1; December 31 has expired.
    expected = ((math.log(10) + math.log(20)) * .125 + math.log(2)) / (2 * .125 + 2)
    assert fitted['index']('f', '2020-04-01') == expected
